from solution import anti_shuffle
import pytest
from hypothesis import given
import hypothesis.strategies as st


def _reference(s):
    # Obviously-correct model: split on single space ' ' preserving
    # empties (hence preserving exact blank-space layout), sort each word by ascii.
    return ' '.join(''.join(sorted(word)) for word in s.split(' '))


# ---- explicit examples from spec ----

def test_example_Hi():
    assert anti_shuffle('Hi') == 'Hi'


def test_example_hello():
    assert anti_shuffle('hello') == 'ehllo'


def test_example_Hello_World():
    assert anti_shuffle('Hello World!!!') == 'Hello !!!Wdlor'


def test_example_empty_string():
    assert anti_shuffle('') == ''


def test_example_single_space_preserved():
    assert anti_shuffle(' ') == ' '


def test_example_all_spaces_preserved():
    assert anti_shuffle('   ') == '   '


def test_example_multiple_spaces_preserved():
    # 'hello  world' -> each word sorted, double space kept
    assert anti_shuffle('hello  world') == 'ehllo  dlorw'


def test_example_leading_space_preserved():
    assert anti_shuffle(' hello') == ' ehllo'


def test_example_trailing_space_preserved():
    assert anti_shuffle('hello ') == 'ehllo '


def test_example_leading_trailing_multiple_spaces():
    assert anti_shuffle('  hello  world  ') == '  ehllo  dlorw  '


def test_example_tabs_not_collapsed_single_word():
    # no ' ' present, whole string is one word sorted by ascii
    s = 'bca'
    assert anti_shuffle(s) == 'abc'


# ---- property-based tests ----

_printable_no_other_ws = list("abcXYZ0129!@#%.,:;?") + [' ']

@given(st.text(alphabet=st.sampled_from(_printable_no_other_ws), max_size=30))
def test_property_length_preserved(s):
    assert len(anti_shuffle(s)) == len(s)


@given(st.text(alphabet=st.sampled_from(_printable_no_other_ws), max_size=30))
def test_property_space_positions_preserved(s):
    r = anti_shuffle(s)
    assert len(r) == len(s)
    for i, ch in enumerate(s):
        assert (ch == ' ') == (r[i] == ' ')


@given(st.text(alphabet=st.sampled_from(_printable_no_other_ws), max_size=30))
def test_property_equivalence_to_reference_model(s):
    assert anti_shuffle(s) == _reference(s)


@given(st.text(alphabet=st.sampled_from(_printable_no_other_ws), max_size=30))
def test_property_each_word_sorted_ascending_ascii(s):
    r = anti_shuffle(s)
    # same number of ' '-separated tokens (including empties from touching spaces)
    assert len(r.split(' ')) == len(s.split(' '))
    for word in r.split(' '):
        assert list(word) == sorted(word)
        # sorted by ascii value explicitly
        assert [ord(c) for c in word] == sorted(ord(c) for c in word)


@given(st.text(alphabet=st.sampled_from(_printable_no_other_ws), max_size=30))
def test_property_global_multiset_preserved(s):
    r = anti_shuffle(s)
    assert sorted(r) == sorted(s)


@given(st.text(alphabet=st.sampled_from(_printable_no_other_ws), max_size=30))
def test_property_idempotence(s):
    once = anti_shuffle(s)
    assert anti_shuffle(once) == once


@given(st.text(alphabet=st.sampled_from(_printable_no_other_ws), max_size=30))
def test_property_word_count_preserved(s):
    r = anti_shuffle(s)
    assert len(s.split(' ')) == len(r.split(' '))


@given(
    st.lists(
        st.text(alphabet=st.sampled_from(list("abcXYZ019!#")), min_size=1, max_size=8),
        min_size=0,
        max_size=5,
    ),
    st.lists(
        st.sampled_from([' ', '  ', '   ']),
        min_size=0,
        max_size=6,
    ),
)
def test_property_metamorphic_space_layout(words, gaps):
    # Build string with known words and known gaps; spaces must be untouched
    # and each word independently sorted.
    parts = []
    for i, w in enumerate(words):
        parts.append(w)
        if i < len(gaps):
            # insert gap after word to create leading/trailing/touching spaces
            parts.append(gaps[i])
    # also allow leading gap
    if len(gaps) > len(words):
        parts = [gaps[-1]] + parts
    s = ''.join(parts)
    # restrict to contract: str only, no other whitespace
    r = anti_shuffle(s)
    assert r == _reference(s)
    assert len(r) == len(s)


@given(st.text(alphabet=st.sampled_from(list("cbaCBA321! ")), max_size=20))
def test_property_sorting_matches_python_sorted(s):
    # each output word must equal python sorted() of corresponding input word
    r = anti_shuffle(s)
    for in_w, out_w in zip(s.split(' '), r.split(' ')):
        assert out_w == ''.join(sorted(in_w))
